{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale input item embeddings by a bounded training-frequency feature computed separately for each dataset. This may distinguish established preferences from rare events while preserving learned embeddings, SASRec topology, readout, loss and optimizer. The feature is a checkpoint buffer; the embedded predictor imports SASRec and loads it automatically, preserving identical inference.",
      "edits": [
        {
          "find": "NUM_EPOCHS   = int(os.environ.get(\"SASREC_EPOCHS\",    \"300\"))",
          "replace": "NUM_EPOCHS   = min(200, int(os.environ.get(\"SASREC_EPOCHS\", \"200\")))"
        },
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        },
        {
          "find": "        self.itemnum = itemnum\n\n        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)",
          "replace": "        self.itemnum = itemnum\n        self.register_buffer(\"input_frequency_scale\", torch.ones(itemnum + 1))\n        self.input_frequency_scale[0] = 0.0\n\n        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)"
        },
        {
          "find": "        seq_emb = self.item_emb(seq) * (self.hidden_units ** 0.5)",
          "replace": "        seq_emb = self.item_emb(seq) * (self.hidden_units ** 0.5)\n        seq_emb = seq_emb * self.input_frequency_scale[seq].unsqueeze(-1)"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY, betas=(0.9, 0.98))",
          "replace": "    training_counts = np.zeros(itemnum + 1, dtype=np.float64)\n    for history in user_train.values():\n        np.add.at(training_counts, np.asarray(history, dtype=np.int64), 1.0)\n    training_counts[0] = 0.0\n    log_counts = np.log1p(training_counts)\n    denominator = max(float(log_counts.max()), 1e-12)\n    frequency_scale = 0.75 + 0.5 * log_counts / denominator\n    frequency_scale[0] = 0.0\n    with torch.no_grad():\n        model.input_frequency_scale.copy_(torch.as_tensor(\n            frequency_scale,\n            dtype=model.input_frequency_scale.dtype,\n            device=device,\n        ))\n\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY, betas=(0.9, 0.98))"
        }
      ]
    }
  ],
  "change_summary": "Add checkpointed, training-only frequency scaling to SASRec input embeddings across all four datasets. Preserve single-model routing and existing training behavior; enforce the required 200-epoch cap and DATA_DIR environment lookup."
}
